bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 -B scripts/userbot_test_client.py health || true
docker exec -i deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module <<'JS'
import fs from 'node:fs';
import https from 'node:https';
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE,'utf8').trim();
async function call(method){
 return new Promise(resolve=>{
  const req=https.get('https://api.telegram.org/bot'+token+'/'+method,{family:4,timeout:12000},res=>{
   let s='';res.on('data',c=>s+=c);res.on('end',()=>{try{const j=JSON.parse(s);resolve({http:res.statusCode,ok:j.ok===true,result:j.result});}catch{resolve({http:res.statusCode,ok:false});}});
  });req.on('timeout',()=>req.destroy());req.on('error',e=>resolve({ok:false,error:e.code||'NETWORK_ERROR'}));
 });
}
const me=await call('getMe'),w=await call('getWebhookInfo');
console.log('BOT_API_IDENTITY',JSON.stringify({ok:me.ok,http:me.http,error:me.error,expected:me.result?.username?.toLowerCase()==='gaybbs_bot'}));
console.log('BOT_API_UPDATES',JSON.stringify({ok:w.ok,http:w.http,error:w.error,webhook:!!w.result?.url,pending:w.result?.pending_update_count,last_error:!!w.result?.last_error_date,allowed:w.result?.allowed_updates}));
